(function(){
'use strict';
const ENH='20260915f-context';
const css=`
.mp-search-card{margin-bottom:14px;padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:16px}.mp-search-card h2{margin:0 0 6px;font-size:21px}.mp-search-card p{margin:0 0 15px;color:var(--ink2);max-width:900px}.mp-search-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px}.mp-search-row input{font-size:15px;padding:13px 14px}.mp-modes{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.mp-mode{background:transparent;color:var(--ink2);padding:7px 10px}.mp-mode.active{background:var(--raised);color:var(--ink);border-color:#3b4d61}.mp-coverage{margin-top:11px;padding:9px 11px;border:1px solid #594a20;background:#211d10;border-radius:8px;color:#f1d783;font-size:11px;line-height:1.45}.mp-match{display:inline-flex;border:1px solid var(--line2);border-radius:999px;padding:3px 7px;font-size:9px;color:var(--blue);margin-bottom:5px}.mp-searching{opacity:.55;pointer-events:none}.mp-side-title{margin-bottom:5px}.mp-hidden{display:none!important}.mp-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.mp-mini{padding:5px 8px;font-size:10px;background:transparent}.mp-mini.primaryish{border-color:#28584e;color:var(--accent)}
.mp-context{position:fixed;inset:0;background:rgba(2,5,9,.72);display:flex;justify-content:flex-end;z-index:70}.mp-context.hidden{display:none}.mp-context-panel{width:min(1080px,96vw);height:100%;overflow:auto;background:var(--canvas);border-left:1px solid var(--line2)}.mp-context-head{position:sticky;top:0;z-index:3;background:rgba(10,15,24,.97);border-bottom:1px solid var(--line);padding:20px}.mp-context-title{font-size:20px;margin:5px 0 8px}.mp-kpis{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:8px;margin-top:14px}.mp-kpi{padding:11px;background:var(--panel);border:1px solid var(--line);border-radius:9px}.mp-kpi .n{font-size:20px;font-weight:750}.mp-kpi .k{font-size:9px;color:var(--ink3);text-transform:uppercase;letter-spacing:.06em;margin-top:3px}.mp-context-section{padding:17px 20px;border-bottom:1px solid var(--line)}.mp-context-section h3{font-size:12px;margin:0 0 10px}.mp-rel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.mp-rel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:9px}.mp-rel strong{display:block;font-size:11px;line-height:1.35}.mp-rel span{font-size:10px;color:var(--ink3)}.mp-context-note{padding:9px 11px;border:1px solid #594a20;background:#211d10;border-radius:8px;color:#f1d783;font-size:10px;line-height:1.4}.mp-tender-row{cursor:pointer}.mp-tender-row:hover td{background:var(--panel2)}
@media(max-width:850px){.mp-search-row{grid-template-columns:1fr}.mp-kpis{grid-template-columns:repeat(2,1fr)}.mp-rel-grid{grid-template-columns:1fr}.mp-context-panel{width:100vw}}
`;
const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);
let mode='all',last=[];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const d=v=>{if(!v)return '—';const x=new Date(v);return Number.isNaN(x.getTime())?String(v):new Intl.DateTimeFormat('es-CL',{dateStyle:'medium'}).format(x)};
const isCode=q=>/^\d{2,8}-\d{1,5}-[A-Z0-9]{2,6}$/i.test(String(q).trim());
function matchText(r){if(r.match_type==='proveedor')return r.participant_name||r.match_label||'Proveedor';if(r.match_type==='item')return r.item_description||r.match_label||'Ítem';if(r.match_type==='organismo')return r.match_label||r.buyer_name||'Organismo';return r.match_label||r.title||r.tender_code}
function coverageText(meta){const months=[...new Set((meta?.coverage||[]).filter(x=>Number(x.tender_ok)>0).map(x=>`${x.source_year}-${String(x.source_month).padStart(2,'0')}`))];return `<strong>Índice piloto:</strong> ${e(meta?.indexed_tenders||0)} licitaciones · ${e(meta?.indexed_items||'—')} ítems · ${e(meta?.indexed_participants||'—')} participantes. Período observado ${e(d(meta?.min_date))} → ${e(d(meta?.max_date))}${months.length?` · ${e(months.length)} mes(es) representado(s)`:''}. <strong>No equivale al universo completo de Mercado Público todavía.</strong>`}
function renderSearch(rows,meta){last=rows||[];const count=document.getElementById('count'),table=document.getElementById('table'),source=document.getElementById('sourcebar'),status=document.getElementById('status');if(count)count.textContent=String(last.length);if(source)source.innerHTML=`<span class="pill ok">búsqueda transversal</span><span class="pill">${e(meta?.mode||mode)}</span><span class="pill">${e(meta?.latency_ms||'—')} ms</span><span class="pill">${e(meta?.indexed_tenders||0)} indexadas</span>`;if(status)status.textContent='Resultados del índice piloto';const cov=document.getElementById('mpCoverage');if(cov)cov.innerHTML=coverageText(meta);if(!table)return;if(!last.length){table.innerHTML='<div class="empty">No se encontraron coincidencias dentro de la cobertura actualmente indexada.</div>';return;}table.innerHTML=`<table><thead><tr><th>Coincidencia</th><th>Licitación relacionada</th><th>Organismo</th><th>Publicación</th></tr></thead><tbody>${last.map((r,i)=>`<tr><td><span class="mp-match">${e(r.match_type)}</span><div><strong>${e(matchText(r))}</strong></div>${r.participant_rut?`<div class="tiny">RUT ${e(r.participant_rut)}</div>`:''}${r.product_code?`<div class="tiny">UNSPSC ${e(r.product_code)}</div>`:''}<div class="mp-actions">${r.match_type!=='licitacion'?`<button class="mp-mini primaryish" data-context="${i}">Ver contexto</button>`:''}</div></td><td><div class="code">${e(r.tender_code)}</div><strong>${e(r.title||'—')}</strong><div class="tiny">${e(r.status||'')}</div><div class="mp-actions"><button class="mp-mini" data-open="${e(r.tender_code)}">Abrir ficha en vivo</button></div></td><td>${e(r.buyer_name||'—')}</td><td>${e(d(r.publication_date))}</td></tr>`).join('')}</tbody></table>`;table.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>window.openCode(x.dataset.open));table.querySelectorAll('[data-context]').forEach(x=>x.onclick=()=>openContext(last[Number(x.dataset.context)]));}
async function search(){const q=String(document.getElementById('mpQ')?.value||'').trim();if(q.length<2)return;if(isCode(q)){window.openCode(q);return;}const card=document.getElementById('mpSearchCard'),btn=document.getElementById('mpSearchBtn');card?.classList.add('mp-searching');if(btn)btn.textContent='Buscando…';try{const out=await window.api('search',{query:q,mode,limit:120});renderSearch(out.rows||[],out.meta||{});}catch(err){const table=document.getElementById('table');if(table)table.innerHTML=`<div class="empty">${e(err?.message||err)}</div>`;}finally{card?.classList.remove('mp-searching');if(btn)btn.textContent='Buscar';}}
function ensureContext(){let x=document.getElementById('mpContextDrawer');if(x)return x;x=document.createElement('div');x.id='mpContextDrawer';x.className='mp-context hidden';x.innerHTML='<div class="mp-context-panel"><div id="mpContextBody"></div></div>';document.body.appendChild(x);x.onclick=ev=>{if(ev.target===x)x.classList.add('hidden')};return x}
function relationCards(rows){return rows?.length?`<div class="mp-rel-grid">${rows.map(x=>`<div class="mp-rel"><strong>${e(x.label)}</strong><span>${e(x.count)} proceso(s)</span></div>`).join('')}</div>`:'<div class="tiny">Sin datos suficientes en el índice actual.</div>'}
async function openContext(r){const drawer=ensureContext(),body=document.getElementById('mpContextBody');drawer.classList.remove('hidden');body.innerHTML='<div class="empty">Cargando contexto indexado…</div>';const payload={entity_type:r.match_type};if(r.match_type==='proveedor'){payload.rut=r.participant_rut||'';payload.name=r.participant_name||r.match_label||''}else if(r.match_type==='organismo'){payload.rut=r.buyer_rut||'';payload.name=r.buyer_name||r.match_label||''}else if(r.match_type==='item'){payload.product_code=r.product_code||'';payload.description=r.item_description||r.match_label||''}try{const out=await window.api('context',payload),x=out.entity||{},t=out.tenders||[];body.innerHTML=`<div class="mp-context-head"><div style="display:flex;justify-content:space-between;gap:12px"><div><span class="mp-match">${e(x.type)}</span><div class="mp-context-title">${e(x.label||'Contexto')}</div><div class="tiny">${x.rut?`RUT ${e(x.rut)}`:''}${x.product_code?`UNSPSC ${e(x.product_code)}`:''}</div></div><button id="mpCtxClose" class="ghost">Cerrar</button></div><div class="mp-kpis"><div class="mp-kpi"><div class="n">${e(x.tender_count||0)}</div><div class="k">Licitaciones indexadas</div></div><div class="mp-kpi"><div class="n">${e(x.buyer_count||0)}</div><div class="k">Organismos relacionados</div></div><div class="mp-kpi"><div class="n">${e(x.supplier_count||0)}</div><div class="k">Proveedores relacionados</div></div><div class="mp-kpi"><div class="n">${e(d(x.min_date))}</div><div class="k">Desde · hasta ${e(d(x.max_date))}</div></div></div></div><div class="mp-context-section"><div class="mp-context-note">Estos indicadores describen únicamente la cobertura actualmente indexada. No constituyen scoring, señal de riesgo ni una afirmación sobre el universo completo de Mercado Público.</div></div>${x.type!=='organismo'?`<div class="mp-context-section"><h3>Principales organismos relacionados</h3>${relationCards(out.top_buyers)}</div>`:''}${x.type!=='proveedor'?`<div class="mp-context-section"><h3>Principales proveedores relacionados</h3>${relationCards(out.top_suppliers)}</div>`:''}${x.type!=='item'?`<div class="mp-context-section"><h3>Productos / ítems más frecuentes</h3>${relationCards(out.top_items)}</div>`:''}<div class="mp-context-section"><h3>Licitaciones relacionadas</h3>${t.length?`<div style="overflow:auto"><table><thead><tr><th>Código</th><th>Licitación</th><th>Organismo</th><th>Publicación</th><th>Estado</th></tr></thead><tbody>${t.map(z=>`<tr class="mp-tender-row" data-ctx-open="${e(z.tender_code)}"><td class="code">${e(z.tender_code)}</td><td><strong>${e(z.title||'—')}</strong></td><td>${e(z.buyer_name||'—')}</td><td>${e(d(z.publication_date))}</td><td>${e(z.status_details||z.status||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tiny">Sin licitaciones relacionadas en la cobertura actual.</div>'}</div>`;document.getElementById('mpCtxClose').onclick=()=>drawer.classList.add('hidden');body.querySelectorAll('[data-ctx-open]').forEach(z=>z.onclick=()=>window.openCode(z.dataset.ctxOpen));}catch(err){body.innerHTML=`<div class="fatal">${e(err?.message||err)}</div>`;}}
async function loadIndexStatus(){try{const out=await window.api('index_status',{}),cov=document.getElementById('mpCoverage');if(cov)cov.innerHTML=coverageText(out.meta||{});}catch{}}
function install(){const shell=document.querySelector('.shell'),top=document.querySelector('.top'),workspace=document.querySelector('.workspace');if(!shell||!top||!workspace||document.getElementById('mpSearchCard'))return false;const card=document.createElement('section');card.id='mpSearchCard';card.className='mp-search-card';card.innerHTML=`<h2>¿Qué quieres encontrar?</h2><p>Busca sin indicar fecha por proveedor, servicio público, producto/ítem o licitación. La fecha queda como exploración complementaria.</p><div class="mp-search-row"><input id="mpQ" placeholder="RUT o proveedor · organismo · producto/UNSPSC · código o título de licitación"><button id="mpSearchBtn" class="primary">Buscar</button></div><div class="mp-modes"><button class="mp-mode active" data-m="all">Todos</button><button class="mp-mode" data-m="proveedor">Proveedores</button><button class="mp-mode" data-m="organismo">Servicios públicos</button><button class="mp-mode" data-m="item">Productos / ítems</button><button class="mp-mode" data-m="licitacion">Licitaciones</button></div><div id="mpCoverage" class="mp-coverage">Leyendo cobertura del índice piloto…</div>`;top.insertAdjacentElement('afterend',card);document.getElementById('mpSearchBtn').onclick=search;document.getElementById('mpQ').onkeydown=x=>{if(x.key==='Enter')search()};card.querySelectorAll('.mp-mode').forEach(b=>b.onclick=()=>{mode=b.dataset.m;card.querySelectorAll('.mp-mode').forEach(x=>x.classList.toggle('active',x===b));});const side=workspace.querySelector('.side');if(side){const h=side.querySelector('h3');if(h){h.textContent='Exploración por fecha';h.classList.add('mp-side-title')}const tiny=side.querySelector('.tiny');if(tiny)tiny.textContent='Opción secundaria para revisar las licitaciones publicadas en un día específico.';side.querySelector('#filter')?.closest('.field')?.classList.add('mp-hidden');side.querySelector('#state')?.closest('.field')?.classList.add('mp-hidden');}const hero=workspace.querySelector('.hero');if(hero){const lab=hero.querySelector('label');if(lab)lab.textContent='Abrir licitación por código exacto';}const p=top.querySelector('.brand p');if(p)p.textContent='Piloto independiente · búsqueda transversal + API en vivo';const badges=top.querySelector('.pills')||top.querySelector('[style*="display:flex"]');if(badges){const x=document.createElement('span');x.className='pill';x.textContent='context '+ENH;badges.insertBefore(x,badges.lastElementChild);}ensureContext();loadIndexStatus();return true}
function wait(){if(install())return;const mo=new MutationObserver(()=>{if(install())mo.disconnect()});mo.observe(document.documentElement,{subtree:true,childList:true});setTimeout(()=>mo.disconnect(),120000)}wait();
})();
